<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { showFailToast, showSuccessToast } from 'vant'; import { useRoute, useRouter } from 'vue-router'; import { api, type Expense, type Sale } from '../api'; import { useWorkspaceStore } from '../stores/workspace'; import { formatDateTime } from '../utils/dateTime'; import AppBottomNavigation from '../components/AppBottomNavigation.vue';
const route=useRoute();const router=useRouter();const store=useWorkspaceStore();const batchId=computed(()=>String(route.params.id));const tab=ref<'sales'|'expenses'>('sales');const sales=ref<Sale[]>([]);const expenses=ref<Expense[]>([]);const loading=ref(true);const error=ref('');const showReverse=ref(false);const reverseType=ref<'sale'|'expense'>('sale');const reverseId=ref('');const reverseReason=ref('');const reversing=ref(false);const canEdit=computed(()=>{const b=store.batches.find((x)=>x.id===batchId.value);return Boolean(b&&(b.role==='owner'||b.role==='editor'||store.canManageWorkspace));});
async function load(){loading.value=true;error.value='';try{const [s,e]=await Promise.all([api.get<Sale[]>(`/batches/${batchId.value}/sales`),api.get<Expense[]>(`/batches/${batchId.value}/expenses`)]);sales.value=s.data;expenses.value=e.data;}catch{error.value='交易记录加载失败，请重试';}finally{loading.value=false;}}function ask(type:'sale'|'expense',id:string){reverseType.value=type;reverseId.value=id;reverseReason.value='';showReverse.value=true;}async function reverse(){if(!reverseReason.value.trim()){showFailToast('请填写撤销原因');return;}reversing.value=true;try{await api.post(`/batches/${batchId.value}/${reverseType.value==='sale'?'sales':'expenses'}/${reverseId.value}/reversals`,{reason:reverseReason.value.trim()});showReverse.value=false;showSuccessToast(reverseType.value==='sale'?'销售已撤销，库存已恢复':'费用已撤销');await load();}catch(e:unknown){showFailToast((e as {response?:{data?:{message?:string}}}).response?.data?.message||'撤销失败');}finally{reversing.value=false;}}onMounted(async()=>{if(!store.workspaces.length)await store.load();await load();});
</script>
<template><div class="transaction-page" data-ai-id="transaction-page"><van-nav-bar title="交易" left-text="返回" left-arrow data-ai-id="transaction-topbar" @click-left="router.push(`/batches/${batchId}`)"/><div v-if="loading" class="state"><van-loading>正在加载交易记录…</van-loading></div><van-empty v-else-if="error" :description="error"><van-button size="small" type="primary" @click="load">重试</van-button></van-empty><main v-else class="content"><p v-if="!canEdit" class="readonly">只读权限 · 当前角色只能查看交易记录。</p><div class="tabs" data-ai-id="transaction-tabs"><button :class="{active:tab==='sales'}" data-ai-id="transaction-sales-tab" @click="tab='sales'">销售</button><button :class="{active:tab==='expenses'}" data-ai-id="transaction-expenses-tab" @click="tab='expenses'">费用</button></div><section v-if="tab==='sales'" data-ai-id="sale-list"><header><span>销售款记在卖出人名下</span><van-button v-if="canEdit" type="primary" size="small" data-ai-id="sale-create" @click="router.push(`/batches/${batchId}/transactions/sales/new`)">记录销售</van-button></header><van-empty v-if="!sales.length" description="还没有销售记录" data-ai-id="sale-empty"/><article v-for="s in sales" :key="s.id" class="item" :data-ai-id="`sale-item-${s.id}`"><div><strong>{{s.productName}} · ¥{{s.totalPrice}} <van-tag v-if="s.reversalReason" type="danger">已撤销</van-tag></strong><span>{{s.sellerUsername}} 卖出并收款 · {{s.quantity}} 件</span><small>{{formatDateTime(s.occurredAt)}}<template v-if="s.reversalReason"> · 原因：{{s.reversalReason}}</template></small></div><button v-if="canEdit&&!s.reversalReason" class="reverse" :data-ai-id="`sale-reversal-${s.id}`" @click="ask('sale',s.id)">撤销</button></article></section><section v-else data-ai-id="expense-list"><header><span>记录谁实际垫付的费用</span><van-button v-if="canEdit" type="primary" size="small" data-ai-id="expense-create" @click="router.push(`/batches/${batchId}/transactions/expenses/new`)">记录费用</van-button></header><van-empty v-if="!expenses.length" description="还没有费用记录" data-ai-id="expense-empty"/><article v-for="e in expenses" :key="e.id" class="item" :data-ai-id="`expense-item-${e.id}`"><div><strong>{{e.name}} · ¥{{e.amount}} <van-tag v-if="e.reversalReason" type="danger">已撤销</van-tag></strong><span>{{e.payerUsername}} 付款{{e.saleId?' · 已关联销售':' · 批次费用'}}</span><small>{{formatDateTime(e.occurredAt)}}<template v-if="e.reversalReason"> · 原因：{{e.reversalReason}}</template></small></div><button v-if="canEdit&&!e.reversalReason" class="reverse" :data-ai-id="`expense-reversal-${e.id}`" @click="ask('expense',e.id)">撤销</button></article></section></main></div><van-dialog v-model:show="showReverse" :title="reverseType==='sale'?'撤销销售':'撤销费用'" :show-cancel-button="false" :show-confirm-button="false" :data-ai-id="reverseType==='sale'?'sale-reversal-dialog':'expense-reversal-dialog'"><p class="dialog-note">{{reverseType==='sale'?'撤销后库存会恢复；请再重新填写正确销售。':'撤销不会删除原费用，会保留本次原因。'}}</p><van-field v-model="reverseReason" label="撤销原因" type="textarea" rows="2" :data-ai-id="reverseType==='sale'?'sale-reversal-reason':'expense-reversal-reason'"/><template #footer><div class="dialog-actions"><van-button plain :disabled="reversing" :data-ai-id="reverseType==='sale'?'sale-reversal-cancel':'expense-reversal-cancel'" @click="showReverse=false">取消</van-button><van-button type="danger" :loading="reversing" :data-ai-id="reverseType==='sale'?'sale-reversal-confirm-action':'expense-reversal-confirm-action'" @click="reverse">确认撤销</van-button></div></template></van-dialog><AppBottomNavigation/></template>
<style scoped>.transaction-page{min-height:100vh;padding-bottom:66px;background:#f5f7fb}.transaction-page :deep(.van-nav-bar){position:sticky;top:0;z-index:2}.content{padding:16px}.readonly{padding:10px 12px;background:#edf1ff;color:#2949aa;border-radius:8px;font-size:13px}.tabs{display:grid;grid-template-columns:1fr 1fr;margin-bottom:14px;border:1px solid #cfd6e2;border-radius:9px;overflow:hidden;background:#fff}.tabs button{min-height:44px;border:0;background:transparent;color:#536078;font:inherit}.tabs button.active{background:#3657c8;color:#fff;font-weight:600}.content section header{display:flex;justify-content:space-between;align-items:center;min-height:44px;margin-bottom:8px;color:#71809a;font-size:12px}.content section header :deep(.van-button){min-height:38px}.item{display:flex;justify-content:space-between;align-items:center;gap:10px;min-height:82px;margin-top:8px;padding:12px;border-radius:10px;background:#fff;box-shadow:0 1px 0 #e4e8f0}.item strong,.item span,.item small{display:block}.item strong{margin-bottom:6px;font-size:15px}.item span,.item small{color:#71809a;font-size:12px}.item small{margin-top:4px}.reverse{min-width:44px;min-height:44px;border:0;background:transparent;color:#b42318;font:inherit}.dialog-note{margin:0;padding:0 16px 10px;color:#71809a;font-size:13px}.dialog-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:12px}.dialog-actions :deep(.van-button){min-height:44px}.state{display:grid;min-height:60vh;place-items:center}</style>
